# changed, so the supervisor's matching check for that field is exercised on
# its own. The supervisor must refuse it. See
# test/unit/AnalysisSupervisorTest.v3.
import os
import struct
import sys
import time

FIELD = "__FIELD__"  # one of "protocol", "version", "revision"
REQUEST_FD = 3  # AnalysisWire.REQUEST_FD
RESULT_FD = 4  # AnalysisWire.RESULT_FD
WORKER_ARG = "--serve"  # AnalysisWire.WORKER_ARG
WATCHDOG_SECONDS = 60.0


def sleb(value, bits):
    """Encodes {value} as signed LEB128."""
    out = bytearray()
    while True:
        byte = value & 0x7F
        value >>= 7
        last = (value == 0 and not (byte & 0x40)) or (value == -1 and (byte & 0x40))
        if not last:
            byte |= 0x80
        out.append(byte)
        if last:
            return bytes(out)


def read_sleb(data, i):
    result = 0
    shift = 0
    while True:
        byte = data[i]
        i += 1
        result |= (byte & 0x7F) << shift
        shift += 7
        if not (byte & 0x80):
            if byte & 0x40:
                result |= -1 << shift
            break
    return result, i


def read_string(data, i):
    length, i = read_sleb(data, i)
    if length < 0:
        return None, i
    return data[i:i + length].decode("utf-8"), i + length


def parse_frame(frame):
    """The handshake's (protocol, version, revision, heap) fields."""
    (length,) = struct.unpack("<I", frame[:4])
    payload = frame[4:4 + length]
    if payload[0] != 1:
        raise SystemExit("not a HELLO handshake frame")
    i = 1
    protocol, i = read_sleb(payload, i)
    version, i = read_string(payload, i)
    revision, i = read_string(payload, i)
    heap, i = read_sleb(payload, i)
    if i != len(payload):
        raise SystemExit("trailing bytes in the handshake")
    return protocol, version, revision, heap


def encode_frame(protocol, version, revision, heap):
    payload = bytearray([1])
    payload += sleb(protocol, 32)
    payload += sleb(len(version), 32) + version.encode("utf-8")
    payload += sleb(len(revision), 32) + revision.encode("utf-8")
    payload += sleb(heap, 64)
    return struct.pack("<I", len(payload)) + bytes(payload)


def read_frame(fd):
    header = b""
    while len(header) < 4:
        chunk = os.read(fd, 4 - len(header))
        if not chunk:
            raise SystemExit("the worker closed its result pipe before its handshake")
        header += chunk
    (length,) = struct.unpack("<I", header)
    payload = b""
    while len(payload) < length:
        chunk = os.read(fd, length - len(payload))
        if not chunk:
            raise SystemExit("the worker closed its result pipe mid-frame")
        payload += chunk
    return header + payload


def spawn_real_worker(worker):
    """Runs {worker} as a child with its request and result descriptors, and
    returns (pid, request_read, result_read)."""
    request_read, request_write = os.pipe()
    result_read, result_write = os.pipe()
    devnull = os.open(os.devnull, os.O_RDWR)
    pid = os.fork()
    if pid == 0:
        os.dup2(devnull, 0)
        os.dup2(devnull, 1)
        os.dup2(devnull, 2)
        os.dup2(request_read, REQUEST_FD)
        os.dup2(result_write, RESULT_FD)
        # Close the source descriptors, but never the two just wired up: the
        # pipe ends can sit at fd 3 or 4, where we just pointed them.
        for fd in (devnull, request_read, request_write, result_read, result_write):
            if fd not in (REQUEST_FD, RESULT_FD):
                os.close(fd)
        os.execv(worker, [worker, WORKER_ARG])
        os._exit(127)
    for fd in (request_write, result_write, devnull):
        os.close(fd)
    return pid, request_read, result_read


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    worker = os.path.join(os.path.dirname(here), "virgil-lsp-worker")
    # spawn_real_worker reuses fd 4 for the real worker's result pipe, so save
    # our own result descriptor and restore it afterwards; the handshake we
    # send must go to the supervisor's pipe. (fd 3 is not needed: the
    # interpreter closes it during startup, so we detect our parent dying via
    # getppid instead of watching the request pipe.)
    saved_result = os.dup(RESULT_FD)
    try:
        pid, request_read, result_read = spawn_real_worker(worker)
        try:
            real = read_frame(result_read)
        finally:
            os.kill(pid, 9)
            os.waitpid(pid, 0)
            os.close(request_read)
            os.close(result_read)
        os.dup2(saved_result, RESULT_FD)
    finally:
        os.close(saved_result)
    protocol, version, revision, heap = parse_frame(real)
    if FIELD == "protocol":
        protocol += 1
    elif FIELD == "version":
        version = "0.0.0-test"
    elif FIELD == "revision":
        revision = "test-revision"
    else:
        raise SystemExit(f"unknown field {FIELD}")
    fake = encode_frame(protocol, version, revision, heap)
    # The fake must differ from the real handshake in exactly this one field,
    # so every other byte (including the heap size) is untouched.
    real_fields = parse_frame(real)
    fake_fields = parse_frame(fake)
    if sum(a != b for a, b in zip(real_fields, fake_fields)) != 1:
        raise SystemExit("the fake handshake differs in more than one field")
    if FIELD == "protocol" and fake_fields[0] == real_fields[0]:
        raise SystemExit("the fake protocol version is unchanged")
    if FIELD == "version" and fake_fields[1] == real_fields[1]:
        raise SystemExit("the fake server version is unchanged")
    if FIELD == "revision" and fake_fields[2] == real_fields[2]:
        raise SystemExit("the fake source revision is unchanged")
    os.write(RESULT_FD, fake)
    # Serve until the supervisor kills us. Exit if our parent dies or after the
    # watchdog, so a killed test process never leaves this worker behind.
    parent = os.getppid()
    deadline = time.monotonic() + WATCHDOG_SECONDS
    while os.getppid() == parent and time.monotonic() < deadline:
        time.sleep(0.1)
    return 0


if __name__ == "__main__":
    sys.exit(main())
